select tablename, policyname, cmd, roles, qual, with_check from pg_policies where schemaname = 'public' and tablename in ('services', 'service_blocks', 'invitations') order by tablename, cmd, policyname;
select c.relname as tabla, has_table_privilege('anon', c.oid, 'select') as anon_select, has_table_privilege('anon', c.oid, 'insert') as anon_insert, has_table_privilege('anon', c.oid, 'update') as anon_update, has_table_privilege('anon', c.oid, 'delete') as anon_delete from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relname in ('services', 'service_blocks', 'invitations') order by 1;
do $$ declare sid uuid; org uuid; tid uuid; mid uuid; bid uuid; iid uuid; adm text; lid text; r text := ''; n int; imp uuid := '00000000-0000-0000-0000-00000000dead'; begin
select count(*) into n from pg_trigger where not tgisinternal and tgenabled <> 'D' and tgname ilike '%notify%'; if n > 0 then raise exception 'Hay % triggers de aviso activos: la prueba se detiene para no arriesgar envíos', n; end if;
select s.id, s.organization_id into sid, org from public.services s where s.tipo = 'servicio' order by s.fecha desc limit 1;
select t.id into tid from public.teams t where t.organization_id = org and t.archived_at is null limit 1;
select m.id into mid from public.members m where m.organization_id = org and not exists (select 1 from public.invitations i where i.service_id = sid and i.member_id = m.id and i.team_id = tid) limit 1;
select id into bid from public.service_blocks limit 1; select id into iid from public.invitations limit 1;
select m.email into adm from public.organization_members om join public.members m on m.id = om.person_id where om.role in ('owner', 'admin') and om.organization_id = org and m.email is not null limit 1;
select m.email into lid from public.team_members tm join public.members m on m.id = tm.member_id where tm.is_leader and tm.organization_id = org and m.email is not null and not exists (select 1 from public.organization_members om where om.person_id = tm.member_id and om.role in ('owner', 'admin')) limit 1;
if sid is null or tid is null or mid is null or adm is null or lid is null then raise exception 'Falta un servicio de tipo servicio, un equipo, una persona sin invitación a ese servicio, un administrador o un líder que no sea administrador para probar'; end if;
set local role anon;
begin insert into public.services (fecha, titulo) values ('2099-12-29', 'prueba anon'); r := r || 'FALLO: anon insertó en services; '; exception when insufficient_privilege then r := r || 'OK: anon no inserta en services; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin update public.services set titulo = titulo where id = imp; r := r || 'FALLO: anon pudo actualizar services; '; exception when insufficient_privilege then r := r || 'OK: anon no actualiza services; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin delete from public.services where id = imp; r := r || 'FALLO: anon pudo borrar en services; '; exception when insufficient_privilege then r := r || 'OK: anon no borra en services; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin insert into public.service_blocks (service_id, orden, tipo, titulo) values (sid, 9991, 'bloque', 'prueba'); r := r || 'FALLO: anon insertó en service_blocks; '; exception when insufficient_privilege then r := r || 'OK: anon no inserta en service_blocks; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin update public.service_blocks set orden = orden where id = imp; r := r || 'FALLO: anon pudo actualizar service_blocks; '; exception when insufficient_privilege then r := r || 'OK: anon no actualiza service_blocks; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin delete from public.service_blocks where id = imp; r := r || 'FALLO: anon pudo borrar en service_blocks; '; exception when insufficient_privilege then r := r || 'OK: anon no borra en service_blocks; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin insert into public.invitations (service_id, member_id, team_id) values (sid, mid, tid); r := r || 'FALLO: anon insertó en invitations; '; exception when insufficient_privilege then r := r || 'OK: anon no inserta en invitations; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin update public.invitations set status = status where id = imp; r := r || 'FALLO: anon pudo actualizar invitations; '; exception when insufficient_privilege then r := r || 'OK: anon no actualiza invitations; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin delete from public.invitations where id = imp; r := r || 'FALLO: anon pudo borrar en invitations; '; exception when insufficient_privilege then r := r || 'OK: anon no borra en invitations; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin select count(*) into n from public.services; r := r || 'OK: anon sigue leyendo services (las lecturas públicas no se tocan); '; exception when insufficient_privilege then r := r || 'FALLO: anon ya no lee services; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
reset role;
set local role authenticated; perform set_config('request.jwt.claims', json_build_object('email', adm, 'role', 'authenticated')::text, true);
begin insert into public.services (fecha, titulo) values ('2099-12-30', 'prueba administrador'); r := r || 'OK: el administrador inserta en services; '; exception when insufficient_privilege then r := r || 'FALLO: el administrador no pudo insertar en services; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin insert into public.service_blocks (service_id, orden, tipo, titulo) values (sid, 9992, 'bloque', 'prueba'); r := r || 'OK: el administrador inserta en service_blocks; '; exception when insufficient_privilege then r := r || 'FALLO: el administrador no pudo insertar en service_blocks; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin delete from public.service_blocks where service_id = sid and orden = 9992; get diagnostics n = row_count; r := r || case when n = 1 then 'OK: el administrador borra en service_blocks; ' else 'FALLO: el administrador no borró en service_blocks (' || n || ' filas); ' end; exception when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin update public.services set titulo = titulo where id = sid; get diagnostics n = row_count; r := r || case when n = 0 then 'OK: ni el administrador actualiza services desde el navegador; ' else 'FALLO: el administrador actualizó services (' || n || ' filas); ' end; exception when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin insert into public.invitations (service_id, member_id, team_id) values (sid, mid, tid); r := r || 'FALLO: el administrador insertó en invitations; '; exception when insufficient_privilege then r := r || 'OK: el administrador no inserta en invitations desde el navegador; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
if iid is not null then begin update public.invitations set status = status where id = iid; get diagnostics n = row_count; r := r || case when n = 0 then 'OK: el administrador no actualiza invitations; ' else 'FALLO: el administrador actualizó invitations (' || n || ' filas); ' end; exception when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end; begin delete from public.invitations where id = iid; get diagnostics n = row_count; r := r || case when n = 0 then 'OK: el administrador no borra invitations; ' else 'FALLO: el administrador borró invitations (' || n || ' filas); ' end; exception when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end; else r := r || 'OMITIDO: no hay invitaciones para probar update y delete como administrador; '; end if;
reset role;
set local role authenticated; perform set_config('request.jwt.claims', json_build_object('email', lid, 'role', 'authenticated')::text, true);
begin insert into public.services (fecha, titulo) values ('2099-12-31', 'prueba líder'); r := r || 'FALLO: el líder insertó en services; '; exception when insufficient_privilege then r := r || 'OK: el líder no inserta en services; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin insert into public.service_blocks (service_id, orden, tipo, titulo) values (sid, 9993, 'bloque', 'prueba'); r := r || 'FALLO: el líder insertó en service_blocks; '; exception when insufficient_privilege then r := r || 'OK: el líder no inserta en service_blocks; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin insert into public.invitations (service_id, member_id, team_id) values (sid, mid, tid); r := r || 'FALLO: el líder insertó en invitations; '; exception when insufficient_privilege then r := r || 'OK: el líder no inserta en invitations; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin update public.services set titulo = titulo where id = sid; get diagnostics n = row_count; r := r || case when n = 0 then 'OK: el líder no actualiza services; ' else 'FALLO: el líder actualizó services (' || n || ' filas); ' end; exception when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
if bid is not null then begin delete from public.service_blocks where id = bid; get diagnostics n = row_count; r := r || case when n = 0 then 'OK: el líder no borra en service_blocks; ' else 'FALLO: el líder borró en service_blocks (' || n || ' filas); ' end; exception when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end; else r := r || 'OMITIDO: no hay bloques para probar el borrado como líder; '; end if;
if iid is not null then begin update public.invitations set status = status where id = iid; get diagnostics n = row_count; r := r || case when n = 0 then 'OK: el líder no actualiza invitations; ' else 'FALLO: el líder actualizó invitations (' || n || ' filas); ' end; exception when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end; else r := r || 'OMITIDO: no hay invitaciones para probar update como líder; '; end if;
reset role;
raise exception 'Resultado (se deshace todo): %', r; end $$;
